import{_ as t,c as n,j as e,a as r,o}from"./chunks/framework.CqbvlPrP.js";const f=JSON.parse('{"title":"第二百六十一章 灭尽欢喜贪欲","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/261第二百六十一章 灭尽欢喜贪欲.md","filePath":"meditation/巴利文大藏经/261第二百六十一章 灭尽欢喜贪欲.md"}'),_={name:"meditation/巴利文大藏经/261第二百六十一章 灭尽欢喜贪欲.md"};function s(i,a,l,d,c,p){return o(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第二百六十一章-灭尽欢喜贪欲",tabindex:"-1"},[r("第二百六十一章 灭尽欢喜贪欲 "),e("a",{class:"header-anchor",href:"#第二百六十一章-灭尽欢喜贪欲","aria-label":'Permalink to "第二百六十一章 灭尽欢喜贪欲"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部22相应52经/欢喜的灭尽经第二(蕴相应/蕴篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人），你们应该经常用正确的智慧去观想物质事物、物质身体、感受、念想、行为、认识、分别、判断。如何正确的观想呢？就是你们要经常观想：「物质事物、物质身体、感受、念想、行为、认识、分别、判断是随时在变化的，是无法永远存在的，是无法永恒保持不变的，是无法永远拥有的。物质事物是会衰败、灭亡、消失的，物质身体是会生病、衰老、死亡的。感受、念想、行为、认识、分别、判断是会消退、灭尽、消失的。」比丘们！你们经常这样的去观想，就能逐渐除灭对物质事物、物质身体、感受、念想、行为、认识、分别、判断的贪爱，就能不再执着和挂念物质事物、物质身体、感受、念想、行为、认识、分别、判断，就不会再对物质事物、物质身体、感受、念想、行为、认识、分别、判断生起欢喜，欢喜灭尽了，贪欲也就灭尽了，或者贪欲灭尽了，欢喜也就灭尽了。对物质事物、物质身体、感受、念想、行为、认识、分别、判断的欢喜与贪欲灭尽的时候，你们的内心就完全的从物质事物、物质身体、感受、念想、行为、认识、分别、判断中解脱出来，你们的内心就彻底的从喜怒哀乐等等一切的烦恼和痛苦中解脱出来，比丘们，这就被称为：「完全解脱出来」。",-1)]))}const u=t(_,[["render",s]]);export{f as __pageData,u as default};
